["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Memory of Panic says: Our warband is not strong enough! We must retreat!",
["id"] = "s54_2773",
["timestamp"] = 1786722682,
},
{
["recordedBy"] = "Auteist-Tichondrius",
["typeInfo"] = {
